#include <iostream>
#include <algorithm>
using namespace std;

int n;
int mp[105][105];   // n ≤ 100，预留足够空间

// 顺时针旋转90度：将(x, y)变为(y, n-1-x)，使用引用修改
void rotate(int &x, int &y) {
    int tmp = x;
    x = y;
    y = n - tmp - 1;
}

int main() {
    cin >> n;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
