            // 寻找轨道中的最大值
            int mxval = mp[i][j];
            int x = i, y = j;
            for (int t = 0; t < 4; t++) {
                rotate(x, y);
                mxval = max(mxval, mp[x][y]);
            }
            // 累加操作次数并更新
            for (int t = 0; t < 4; t++) {
